<?php
declare(strict_types=1);
namespace app\common\support;
use think\facade\Db;

final class AssetExchangeService
{
    public function __construct(private int $appid, private array $user){}
    public function overview():array{$asset=$this->asset();$cfg=$this->config((int)$asset['id']);$account=$this->account((int)$asset['id'],false);return ['enabled'=>(int)$cfg['status']===1,'symbol'=>'USDD','available_balance'=>$this->amount($account['available_balance']??0),'rate'=>$this->amount($cfg['rate']),'fee_rate'=>(string)$cfg['fee_rate'],'min_amount'=>$this->amount($cfg['min_amount']),'max_amount'=>$this->amount($cfg['max_amount']),'daily_limit'=>$this->amount($cfg['daily_limit']),'platform_balance'=>number_format((float)($this->user['money']??0),2,'.','')];}
    public function quote(array $data):array{$this->active();$asset=$this->asset();$cfg=$this->config((int)$asset['id']);if((int)$cfg['status']!==1)throw new \RuntimeException('闪兑暂未开放');$amount=$this->positive($data['amount']??0);if(bccomp($amount,(string)$cfg['min_amount'],8)<0||bccomp($amount,(string)$cfg['max_amount'],8)>0)throw new \RuntimeException('兑换数量不在允许范围内');$account=$this->account((int)$asset['id'],false);if(bccomp((string)$account['available_balance'],$amount,8)<0)throw new \RuntimeException('USDD可用余额不足');$gross=bcmul($amount,(string)$cfg['rate'],8);$fee=bcmul($gross,bcdiv((string)$cfg['fee_rate'],'100',8),8);$target=bcsub($gross,$fee,2);if(bccomp($target,'0.00',2)<=0)throw new \RuntimeException('兑换后到账金额必须大于0');$request=$this->request($data['request_id']??'');$hash=hash('sha256',$amount.'|'.$cfg['config_version']);$existing=Db::name('wallet_exchange_order')->where(['appid'=>$this->appid,'user_id'=>$this->uid(),'request_id'=>$request])->find();if($existing){if(!hash_equals((string)$existing['param_hash'],$hash))throw new \RuntimeException('request_id已被其他报价使用');return $this->view($existing);} $now=date('Y-m-d H:i:s');$expire=date('Y-m-d H:i:s',time()+max(15,min(300,(int)$cfg['quote_ttl'])));$token=bin2hex(random_bytes(32));$id=Db::name('wallet_exchange_order')->insertGetId(['appid'=>$this->appid,'user_id'=>$this->uid(),'order_no'=>$this->number('EX'),'request_id'=>$request,'quote_token'=>$token,'source_asset_id'=>(int)$asset['id'],'source_symbol'=>'USDD','source_amount'=>$amount,'rate'=>(string)$cfg['rate'],'fee_rate'=>(string)$cfg['fee_rate'],'fee_amount'=>$fee,'target_amount'=>$target,'config_version'=>(int)$cfg['config_version'],'quote_expire_time'=>$expire,'status'=>'quoted','param_hash'=>$hash,'create_time'=>$now,'update_time'=>$now]);return $this->view(Db::name('wallet_exchange_order')->where('id',$id)->find());}
    public function execute(array $data):array{$this->active();$token=trim((string)($data['quote_token']??''));if(!preg_match('/^[a-f0-9]{64}$/',$token))throw new \InvalidArgumentException('报价凭证无效');Db::startTrans();try{$order=Db::name('wallet_exchange_order')->where(['appid'=>$this->appid,'user_id'=>$this->uid(),'quote_token'=>$token])->lock(true)->find();if(!$order)throw new \RuntimeException('报价不存在');if($order['status']==='completed'){Db::commit();return $this->view($order);}if($order['status']!=='quoted'||strtotime((string)$order['quote_expire_time'])<time())throw new \RuntimeException('报价已过期，请重新获取');$cfg=$this->config((int)$order['source_asset_id'],true);if((int)$cfg['status']!==1||(int)$cfg['config_version']!==(int)$order['config_version'])throw new \RuntimeException('兑换配置已更新，请重新报价');$today=Db::name('wallet_exchange_order')->where(['appid'=>$this->appid,'user_id'=>$this->uid(),'status'=>'completed'])->whereDay('completed_time')->sum('source_amount');if(bccomp(bcadd((string)$today,(string)$order['source_amount'],8),(string)$cfg['daily_limit'],8)>0)throw new \RuntimeException('今日闪兑额度已用完');$user=Db::name('user')->where(['appid'=>$this->appid,'id'=>$this->uid()])->lock(true)->find();if(!$user||(int)$user['wallet_status']!==1)throw new \RuntimeException('钱包当前不可用');$account=$this->account((int)$order['source_asset_id'],true);if(bccomp((string)$account['available_balance'],(string)$order['source_amount'],8)<0)throw new \RuntimeException('USDD可用余额不足');$after=bcsub((string)$account['available_balance'],(string)$order['source_amount'],8);$now=date('Y-m-d H:i:s');$journalId=Db::name('wallet_asset_journal')->insertGetId(['appid'=>$this->appid,'journal_no'=>$this->number('J'),'request_id'=>'exchange-'.$order['order_no'],'business_type'=>'exchange_out','business_no'=>$order['order_no'],'asset_id'=>(int)$order['source_asset_id'],'status'=>1,'param_hash'=>$order['param_hash'],'create_time'=>$now]);Db::name('wallet_asset_account')->where('id',$account['id'])->update(['available_balance'=>$after,'total_out'=>bcadd((string)$account['total_out'],(string)$order['source_amount'],8),'version'=>Db::raw('version+1'),'update_time'=>$now]);Db::name('wallet_asset_entry')->insert(['journal_id'=>$journalId,'account_id'=>$account['id'],'user_id'=>$this->uid(),'direction'=>'debit','available_delta'=>bcsub('0',(string)$order['source_amount'],8),'frozen_delta'=>'0.00000000','available_after'=>$after,'frozen_after'=>$account['frozen_balance'],'remark'=>'USDD闪兑平台余额','create_time'=>$now]);Db::name('user')->where(['appid'=>$this->appid,'id'=>$this->uid()])->update(['money'=>Db::raw('money + '.(string)$order['target_amount'])]);Db::name('transaction_statement')->insert(['appid'=>$this->appid,'userid'=>$this->uid(),'transaction_type'=>1,'transaction_date'=>$now,'transaction_amount'=>(string)$order['target_amount'],'remark'=>'USDD闪兑到账 '.$order['order_no'],'type'=>0,'frozen'=>0]);Db::name('wallet_exchange_order')->where('id',$order['id'])->update(['status'=>'completed','completed_time'=>$now,'update_time'=>$now]);Db::commit();return $this->view(Db::name('wallet_exchange_order')->where('id',$order['id'])->find());}catch(\Throwable $e){Db::rollback();throw $e;}}
    public function orders():array{return Db::name('wallet_exchange_order')->where(['appid'=>$this->appid,'user_id'=>$this->uid()])->order('id desc')->limit(100)->select()->toArray();}
    private function asset():array{$a=Db::name('otc_asset')->where(['appid'=>$this->appid,'symbol'=>'USDD','status'=>1])->find();if(!$a)throw new \RuntimeException('USDD资产未配置');return $a;}
    private function config(int $id,bool $lock=false):array{$q=Db::name('wallet_exchange_config')->where(['appid'=>$this->appid,'source_asset_id'=>$id,'target_type'=>'platform_balance']);if($lock)$q->lock(true);$c=$q->find();if(!$c)throw new \RuntimeException('闪兑配置不存在');return $c;}
    private function account(int $asset,bool $lock):array{$q=Db::name('wallet_asset_account')->where(['appid'=>$this->appid,'user_id'=>$this->uid(),'asset_id'=>$asset]);if($lock)$q->lock(true);return $q->find()?:['available_balance'=>'0.00000000','frozen_balance'=>'0.00000000'];}
    private function active():void{if((int)($this->user['wallet_status']??0)!==1)throw new \RuntimeException('钱包当前不可用');}
    private function positive(mixed $v):string{$s=trim((string)$v);if(!preg_match('/^\d+(\.\d{1,6})?$/',$s)||bccomp($s,'0',8)<=0)throw new \InvalidArgumentException('请输入正确的USDD数量');return bcadd($s,'0',8);}
    private function request(mixed $v):string{$s=trim((string)$v);if(!preg_match('/^[A-Za-z0-9_-]{16,80}$/',$s))throw new \InvalidArgumentException('request_id无效');return $s;}
    private function view(array $o):array{return ['order_no'=>$o['order_no'],'quote_token'=>$o['quote_token'],'source_symbol'=>'USDD','source_amount'=>$this->amount($o['source_amount']),'rate'=>$this->amount($o['rate']),'fee_rate'=>(string)$o['fee_rate'],'fee_amount'=>$this->amount($o['fee_amount']),'target_amount'=>number_format((float)$o['target_amount'],2,'.',''),'expire_time'=>$o['quote_expire_time'],'status'=>$o['status']];}
    private function amount(mixed $v):string{return bcadd((string)$v,'0',8);}private function uid():int{return (int)$this->user['id'];}private function number(string $p):string{return $p.date('YmdHis').strtoupper(bin2hex(random_bytes(6)));}
}
